import { WebSocketServer } from 'ws';
import http from 'node:http';

// 1. O servidor HTTP comum atende os pedidos normais...
const servidor = http.createServer((req, res) => res.end('ok'));

// 2. ...e o WebSocketServer escuta a MESMA porta, no caminho /chat.
const ws = new WebSocketServer({ server: servidor, path: '/chat' });

ws.on('connection', (socket) => {
  // 3. Cada cliente conectado tem um socket = uma linha aberta.
  socket.on('message', (dados) => {
    // 4. Broadcast: repassa para TODOS os clientes conectados.
    for (const cliente of ws.clients) {
      cliente.send(dados.toString());
    }
  });
});

servidor.listen(3000);

import { WebSocketServer } from 'ws';
import http from 'node:http';

// 1. O servidor HTTP que também serve a página (ou uma API normal).
const servidor = http.createServer((req, res) => {
  res.setHeader('content-type', 'text/html; charset=utf-8');
  res.end('Abra o console e conecte em ws://localhost:3000/chat');
});

const ws = new WebSocketServer({ server: servidor, path: '/chat' });

ws.on('connection', (socket) => {
  // 2. Alguém entrou na sala: avisa todo mundo (inclusive o recém-chegado).
  socket.send('bem-vindo! ' + ws.clients.size + ' pessoa(s) na linha');

  socket.on('message', (dados) => {
    const texto = dados.toString();
    // 3. Repassa a mensagem para todos — é assim que um chat funciona.
    for (const cliente of ws.clients) {
      cliente.send(texto);
    }
  });

  socket.on('close', () => {
    // 4. A linha caiu: ninguém precisa perguntar de novo, o evento avisa.
    console.log('alguém saiu; restam', ws.clients.size);
  });
});

servidor.listen(3000);

